const q = $input.first().json.query || {};

const page = Math.max(parseInt(q.page || '1', 10), 1);
const limit = Math.min(Math.max(parseInt(q.limit || '20', 10), 1), 100);
const offset = (page - 1) * limit;

function clean(value) {
  if (value === undefined || value === null || value === '') return null;
  return String(value).trim();
}

function sqlString(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

const status = clean(q.status);
const search = clean(q.search);
const from = clean(q.from);
const to = clean(q.to);

const where = [];

if (status) {
  where.push(`f.status = ${sqlString(status)}`);
}

if (search) {
  const s = sqlString(`%${search}%`);
  where.push(`(
    f.emisor_nombre LIKE ${s}
    OR f.emisor_cuit LIKE ${s}
    OR f.receptor_nombre LIKE ${s}
    OR f.receptor_cuit LIKE ${s}
    OR f.numero_comprobante LIKE ${s}
    OR f.punto_de_venta LIKE ${s}
    OR f.conceptos LIKE ${s}
    OR f.cta_imputacion LIKE ${s}
    OR f.validacion LIKE ${s}
    OR cg.name LIKE ${s}
    OR cc.name LIKE ${s}
  )`);
}

if (from) {
  where.push(`f.fecha_emision >= ${sqlString(from)}`);
}

if (to) {
  where.push(`f.fecha_emision <= ${sqlString(to)}`);
}

const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

const dataQuery = `
SELECT
  f.id,
  f.proveedor_id,
  f.proveedor_match_method,
  f.proveedor_encontrado,

  f.emisor_cuit,
  f.emisor_nombre,
  f.receptor_cuit,
  f.receptor_nombre,

  f.tipo_comprobante,
  f.codigo_comprobante,
  f.punto_de_venta,
  f.numero_comprobante,

  f.fecha_emision,
  f.periodo_desde,
  f.periodo_hasta,
  f.fecha_vencimiento_pago,

  f.subtotal,
  f.importe_total,
  f.conceptos,

  f.cta_imputacion,
  f.validacion,

  f.cost_group_id,
  cg.name AS cost_group_name,

  f.cost_center_id,
  cc.name AS cost_center_name,

  f.amount_bucket,
  f.currency,
  f.cost_subcenter_input,
  f.percepcion_iibb,
  f.percepcion_iibb_pcia,

  f.pdf_url,
  f.status,
  f.error_message,

  f.external_status,
  f.confirmed_at,
  f.confirmed_by,

  f.created_at,
  f.updated_at

FROM facturas_rpa f
LEFT JOIN cost_groups cg ON cg.id = f.cost_group_id
LEFT JOIN cost_centers cc ON cc.id = f.cost_center_id
${whereSql}
ORDER BY f.created_at DESC
LIMIT ${limit}
OFFSET ${offset};
`;

const countQuery = `
SELECT COUNT(*) AS total
FROM facturas_rpa f
LEFT JOIN cost_groups cg ON cg.id = f.cost_group_id
LEFT JOIN cost_centers cc ON cc.id = f.cost_center_id
${whereSql};
`;

return [
  {
    json: {
      page,
      limit,
      offset,
      dataQuery,
      countQuery
    }
  }
];

const queryData = $('Build query listado').first().json;
const facturas = $('MySQL listado facturas').all().map(i => i.json);
const countRows = $('MySQL count facturas').all().map(i => i.json);
const total = countRows[0]?.total || 0;

return [
  {
    json: {
      success: true,
      page: queryData.page,
      limit: queryData.limit,
      total,
      total_pages: Math.ceil(total / queryData.limit),
      data: facturas
    }
  }
];

const q = $input.first().json.query || {};
const id = Number(q.id);

if (!id || !Number.isInteger(id)) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'id es requerido y debe ser numerico'
        }
      }
    }
  ];
}

return [
  {
    json: {
      id,
      query: `
SELECT
  f.*,

  p.nombre AS proveedor_nombre_db,
  p.cuit_dni AS proveedor_cuit_db,
  p.cta_imputacion AS proveedor_cta_imputacion_db,
  p.validacion AS proveedor_validacion_db,

  cg.name AS cost_group_name,
  cg.description AS cost_group_description,

  cc.name AS cost_center_name,
  cc.description AS cost_center_description

FROM facturas_rpa f
LEFT JOIN proveedores_rpa p ON p.id = f.proveedor_id
LEFT JOIN cost_groups cg ON cg.id = f.cost_group_id
LEFT JOIN cost_centers cc ON cc.id = f.cost_center_id
WHERE f.id = ${id}
LIMIT 1;
`
    }
  }
];

const rows = $input.all().map(i => i.json);

if (!rows.length) {
  return [
    {
      json: {
        responseCode: 404,
        body: {
          success: false,
          message: 'Factura no encontrada'
        }
      }
    }
  ];
}

return [
  {
    json: {
      responseCode: 200,
      body: {
        success: true,
        data: rows[0]
      }
    }
  }
];

const body = $input.first().json.body || $input.first().json;

const allowedStatuses = [
  'pending_review',
  'processed',
  'proveedor_no_encontrado',
  'invalid_invoice',
  'error'
];

const id = Number(body.id);

if (!id || !Number.isInteger(id)) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'id es requerido y debe ser numerico'
        }
      }
    }
  ];
}

if (body.status && !allowedStatuses.includes(body.status)) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: `status invalido. Valores permitidos: ${allowedStatuses.join(', ')}`
        }
      }
    }
  ];
}

return [
  {
    json: {
      id,
      body
    }
  }
];

