const base = $('Validar body update').first().json;
const body = base.body;
const proveedorRows = $input.all().map(i => i.json);
const proveedor = proveedorRows[0] || null;

function sqlString(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function sqlNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

const sets = [];

function addString(field, value) {
  if (value !== undefined) {
    sets.push(`${field} = ${sqlString(value)}`);
  }
}

function addNumber(field, value) {
  if (value !== undefined) {
    const n = sqlNumber(value);
    sets.push(`${field} = ${n === null ? 'NULL' : n}`);
  }
}

if (body.proveedor_id !== undefined) {
  if (proveedor) {
    sets.push(`proveedor_id = ${proveedor.id}`);
    sets.push(`proveedor_encontrado = 1`);
    sets.push(`proveedor_match_method = 'nombre'`);
    sets.push(`cta_imputacion = ${sqlString(proveedor.cta_imputacion)}`);
    sets.push(`validacion = ${sqlString(proveedor.validacion)}`);
  } else if (body.proveedor_id === null) {
    sets.push(`proveedor_id = NULL`);
    sets.push(`proveedor_encontrado = 0`);
    sets.push(`proveedor_match_method = 'not_found'`);
  }
}

addString('emisor_cuit', body.emisor_cuit);
addString('emisor_nombre', body.emisor_nombre);
addString('receptor_cuit', body.receptor_cuit);
addString('receptor_nombre', body.receptor_nombre);

addString('tipo_comprobante', body.tipo_comprobante);
addString('codigo_comprobante', body.codigo_comprobante);
addString('punto_de_venta', body.punto_de_venta);
addString('numero_comprobante', body.numero_comprobante);

addString('fecha_emision', body.fecha_emision);
addString('periodo_desde', body.periodo_desde);
addString('periodo_hasta', body.periodo_hasta);
addString('fecha_vencimiento_pago', body.fecha_vencimiento_pago);

addNumber('subtotal', body.subtotal);
addNumber('importe_total', body.importe_total);

addString('conceptos', body.conceptos);
addString('cta_imputacion', body.cta_imputacion);
addString('validacion', body.validacion);

addNumber('cost_group_id', body.cost_group_id);
addNumber('cost_center_id', body.cost_center_id);

addString('amount_bucket', body.amount_bucket);
addString('currency', body.currency);
addString('cost_subcenter_input', body.cost_subcenter_input);

addNumber('percepcion_iibb', body.percepcion_iibb);
addNumber('percepcion_iibb_pcia', body.percepcion_iibb_pcia);

addString('status', body.status);
addString('error_message', body.error_message);

sets.push('updated_at = CURRENT_TIMESTAMP');

if (!sets.length) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'No hay campos para actualizar'
        }
      }
    }
  ];
}

const query = `
UPDATE facturas_rpa
SET ${sets.join(',\n    ')}
WHERE id = ${base.id}
LIMIT 1;
`;

return [
  {
    json: {
      id: base.id,
      query
    }
  }
];

const rows = $input.all().map(i => i.json);

if (!rows.length) {
  return [
    {
      json: {
        responseCode: 404,
        body: {
          success: false,
          message: 'Factura no encontrada luego de actualizar'
        }
      }
    }
  ];
}

return [
  {
    json: {
      responseCode: 200,
      body: {
        success: true,
        message: 'Factura actualizada correctamente',
        data: rows[0]
      }
    }
  }
];

const q = $input.first().json.query || {};
const search = String(q.q || '').trim();

function sqlString(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

if (!search || search.length < 2) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'q es requerido y debe tener al menos 2 caracteres'
        }
      }
    }
  ];
}

const like = sqlString(`%${search}%`);

return [
  {
    json: {
      query: `
SELECT
  id,
  cuit_dni,
  nombre,
  cta_imputacion,
  validacion
FROM proveedores_rpa
WHERE cuit_dni LIKE ${like}
   OR nombre LIKE ${like}
   OR cta_imputacion LIKE ${like}
   OR validacion LIKE ${like}
ORDER BY nombre ASC
LIMIT 20;
`
    }
  }
];

return [
  {
    json: {
      success: true,
      data: $input.all().map(i => i.json)
    }
  }
];

const rows = $input.all().map(i => i.json);

const groupsMap = new Map();

for (const row of rows) {
  if (!groupsMap.has(row.group_id)) {
    groupsMap.set(row.group_id, {
      id: row.group_id,
      name: row.group_name,
      description: row.group_description,
      is_active: !!row.group_is_active,
      centers: []
    });
  }

  if (row.center_id) {
    groupsMap.get(row.group_id).centers.push({
      id: row.center_id,
      cost_group_id: row.group_id,
      name: row.center_name,
      description: row.center_description,
      is_active: !!row.center_is_active
    });
  }
}

return [
  {
    json: {
      success: true,
      data: Array.from(groupsMap.values())
    }
  }
];

const body = $input.first().json.body || $input.first().json;
const id = Number(body.id);

if (!id || !Number.isInteger(id)) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'id es requerido y debe ser numerico'
        }
      }
    }
  ];
}

return [
  {
    json: {
      id,
      body
    }
  }
];

const request = $('Validate confirm body').first().json;
const body = request.body || {};
const rows = $input.all().map(i => i.json);

if (!rows.length) {
  return [
    {
      json: {
        error: true,
        responseCode: 404,
        body: {
          success: false,
          message: 'Factura no encontrada'
        }
      }
    }
  ];
}

const f = rows[0];

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function money(value) {
  const n = Number(value || 0);
  return n.toFixed(2);
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

function formatTaxId(value) {
  const digits = clean(value).replace(/\D/g, '');
  if (digits.length === 11) {
    return `${digits.slice(0, 2)}-${digits.slice(2, 10)}-${digits.slice(10)}`;
  }
  return clean(value);
}

const puntoVenta = clean(f.punto_de_venta);
const numero = clean(f.numero_comprobante);

const payload = {
  invoice_number: `${puntoVenta}-${numero}`,
  invoice_number_part_1: puntoVenta,
  invoice_number_part_2: numero,

  invoice_date: clean(f.fecha_emision),

  customer_name: clean(f.emisor_nombre),
  customer_tax_id: formatTaxId(f.emisor_cuit),

  amount: money(f.importe_total || f.subtotal),
  amount_bucket: clean(body.amount_bucket || f.amount_bucket || 'exento'),
  currency: clean(body.currency || f.currency || 'ARS'),

  description: clean(f.conceptos),
  entidad: clean(f.emisor_nombre),

  cost_group_input: clean(body.cost_group_input || f.cost_group_name),
  cost_center_input: clean(body.cost_center_input || f.cost_center_name),
  cost_subcenter_input: clean(
    body.cost_subcenter_input ||
    f.cost_subcenter_input ||
    f.cost_center_name
  ),

  today: clean(body.today || today()),

  percepcion_iibb: money(body.percepcion_iibb ?? f.percepcion_iibb),
  percepcion_iibb_pcia: money(body.percepcion_iibb_pcia ?? f.percepcion_iibb_pcia)
};

const missing = [];

if (!payload.invoice_number_part_1) missing.push('punto_de_venta');
if (!payload.invoice_number_part_2) missing.push('numero_comprobante');
if (!payload.invoice_date) missing.push('fecha_emision');
if (!payload.customer_name) missing.push('emisor_nombre');
if (!payload.customer_tax_id) missing.push('emisor_cuit');
if (!payload.amount || payload.amount === '0.00') missing.push('amount');
if (!payload.cost_group_input) missing.push('cost_group_input');
if (!payload.cost_center_input) missing.push('cost_center_input');

if (missing.length) {
  return [
    {
      json: {
        error: true,
        responseCode: 400,
        body: {
          success: false,
          message: 'Faltan campos requeridos para confirmar la factura',
          missing,
          payload
        }
      }
    }
  ];
}

return [
  {
    json: {
      invoice_id: f.id,
      payload
    }
  }
];

const before = $('Build confirm payload').first().json;
const httpItem = $input.first().json;

function sqlString(value) {
  if (value === null || value === undefined || value === '') return 'NULL';
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

const isError = !!httpItem.error || httpItem.statusCode >= 400;

const externalResponse = httpItem;
const status = isError ? 'confirmed_error' : 'processed';
const externalStatus = isError ? 'error' : 'success';
const errorMessage = isError
  ? (httpItem.message || httpItem.error?.message || 'Error al cargar factura en sistema externo')
  : null;

const query = `
UPDATE facturas_rpa
SET
  status = ${sqlString(status)},
  external_payload = CAST(${sqlString(JSON.stringify(before.payload))} AS JSON),
  external_response = CAST(${sqlString(JSON.stringify(externalResponse))} AS JSON),
  external_status = ${sqlString(externalStatus)},
  confirmed_at = ${isError ? 'NULL' : 'CURRENT_TIMESTAMP'},
  error_message = ${sqlString(errorMessage)},
  updated_at = CURRENT_TIMESTAMP
WHERE id = ${before.invoice_id}
LIMIT 1;
`;

return [
  {
    json: {
      invoice_id: before.invoice_id,
      success: !isError,
      status,
      external_status: externalStatus,
      error_message: errorMessage,
      payload: before.payload,
      external_response: externalResponse,
      query
    }
  }
];

const result = $('Build update after confirm').first().json;

if (!result.success) {
  return [
    {
      json: {
        responseCode: 502,
        body: {
          success: false,
          message: 'No se pudo cargar la factura en el sistema externo',
          invoice_id: result.invoice_id,
          status: result.status,
          external_status: result.external_status,
          error_message: result.error_message,
          payload: result.payload,
          external_response: result.external_response
        }
      }
    }
  ];
}

return [
  {
    json: {
      responseCode: 200,
      body: {
        success: true,
        message: 'Factura cargada correctamente',
        invoice_id: result.invoice_id,
        status: result.status,
        external_status: result.external_status,
        payload: result.payload,
        external_response: result.external_response
      }
    }
  }
];
